-- Optional supplier photo, stored like Order's delivery photos: a base64 JPEG
-- data URL, empty when there is none. The API re-encodes uploads as JPEG of at
-- most 512 KiB, which is at most 699,075 characters here.
ALTER TABLE suppliers
    ADD COLUMN image text NOT NULL DEFAULT '' CHECK (char_length(image) <= 700000),
    ADD CONSTRAINT deleted_supplier_no_image CHECK (deleted_at IS NULL OR image = '');

-- Template seed photos from data/images, resized to 800 px with metadata removed.
-- Suppliers an admin has since renamed, moved or deleted are left unchanged.
UPDATE suppliers s SET image=v.image
FROM (VALUES
('Anna''s x Soup Union','central-library',
'data:image/jpeg;base64,'),
('NUS Co-op','central-library',
'data:image/jpeg;base64,'),
('Printer @ Com 2','com2',
'data:image/jpeg;base64,'),
('Cool Spot','com2',
'data:image/jpeg;base64,'),
('InstaChef','terrace',
'data:image/jpeg;base64,'),
('Cafe+ Robot Cafe','central-library',
'data:image/jpeg;base64,')
) AS v(name, location_id, image)
WHERE s.name=v.name AND s.location_id=v.location_id AND s.deleted_at IS NULL;
